package com.hotel.management.dao.impl;

import com.hotel.management.dao.IRoomDao;
import com.hotel.management.entity.Room;
import com.hotel.management.hibernateDao.HibernatePaginationSortingDao;
import jakarta.persistence.EntityManager;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public class RoomDaoImpl extends HibernatePaginationSortingDao<Long, Room> implements IRoomDao {
    @Autowired
    public RoomDaoImpl(EntityManager entityManager) {
        super(Room.class, entityManager);
    }

    @Override
    public List<Room> findAvailableRooms(String roomType, Double maxPrice) {
        String hql = "SELECT r FROM Room r WHERE r.status = 'AVAILABLE' " +
                     "AND (:roomType IS NULL OR r.roomType = :roomType) " +
                     "AND (:maxPrice IS NULL OR r.pricePerNight <= :maxPrice)";
        return getEntityManager().createQuery(hql, Room.class)
                .setParameter("roomType", roomType)
                .setParameter("maxPrice", maxPrice)
                .getResultList();
    }
}
```

